  async onLoad() {
    const cart = wx.getStorageSync('checkout_cart')
    if (!cart || !cart.saleId || !Array.isArray(cart.items) || cart.items.length === 0) {
      wx.showToast({ title: '购物车为空', icon: 'none' })
      wx.navigateBack()
      return
    }
    this.setData({ saleId: cart.saleId, cartItems: cart.items })
