    const qtyMap = {}
    for (const d of dishes) qtyMap[d._id] = Number(d.qty || 0)
    const { totalQty, totalAmountFen } = calcTotals(dishes, qtyMap)
    this.setData({ dishes, qtyMap, totalQty, totalAmountYuan: centToEuro(totalAmountFen) })
