      if (qty <= 0) continue
      const old = oldMap.get(dishId)
      const unitPriceCents = Number(old && old.unitPriceCents)
      const dishName = String((old && old.dishName) || '')
      if (!Number.isFinite(unitPriceCents) || unitPriceCents < 0 || !dishName) {
        return fail('BAD_REQUEST', 'Invalid order item')
      }
      const lineTotalCents = unitPriceCents * qty
      totalQty += qty
      totalAmountCents += lineTotalCents
      nextItems.push({ dishId, dishName, unitPriceCents, qty, lineTotalCents })
    }
    if (nextItems.length === 0) return fail('BAD_REQUEST', 'Order cannot be empty, cancel it instead')

    const now = db.serverDate()
    await db.collection('orders').doc(orderId).update({
      data: {
        items: nextItems,
        totals: { qty: totalQty, amountCents: totalAmountCents },
        updatedAt: now,
      },
    })
    await db.collection('orderAuditLogs').add({
      data: {
        orderId,
        action: 'CUSTOMER_UPDATE_ITEMS',
        byOpenId: openId,
        at: now,
      },
    })
    return ok({})
  }

  if (action === 'cancelMyOrder') {
    const { orderId } = event
    if (!orderId) return fail('BAD_REQUEST', 'Missing orderId')
    let r
    try {
      r = await db.collection('orders').doc(orderId).get()
    } catch (err) {
      return fail('ORDER_NOT_FOUND', 'Order not found')
    }
    const order = r.data
    if (!order || order.customerOpenId !== openId) return fail('FORBIDDEN', 'Forbidden')
    if (order.status === 'CANCELLED') return ok({})
    if (order.status !== 'ACTIVE') return fail('ORDER_NOT_EDITABLE', 'Order is not editable')

    const sale = await getSaleById(order.saleId)
    if (!sale || sale.status !== 'OPEN') return fail('ORDER_LOCKED', 'Sale closed, customer cancel disabled')

    const now = db.serverDate()
    await db.collection('orders').doc(orderId).update({
      data: {
        status: 'CANCELLED',
        cancelledAt: now,
        cancelledByOpenId: openId,
        updatedAt: now,
      },
    })
    await db.collection('orderAuditLogs').add({
      data: {
        orderId,
        action: 'CUSTOMER_CANCEL',
        byOpenId: openId,
        at: now,
      },
    })
    return ok({})
  }

  if (action === 'createOrder') {
    const sale = await getActiveSale()
    if (!sale) return fail('NOT_OPEN', 'Not open for ordering')
    const saleId = event.saleId
    if (!saleId || saleId !== sale._id) return fail('NOT_OPEN', 'Not open for ordering')

    const fulfillmentType = event.fulfillmentType
    if (fulfillmentType !== 'delivery' && fulfillmentType !== 'pickup') {
      return fail('BAD_REQUEST', 'Invalid fulfillmentType')
    }

    const phone = normalizePhone(event.phone)
    if (!isPhoneValid(phone)) return fail('INVALID_PHONE', 'Invalid phone')

    const address = event.address
    const acceptDeliverySlot = !!event.acceptDeliverySlot
    if (fulfillmentType === 'delivery') {
      if (!isAddressValid(address)) return fail('INVALID_ADDRESS', 'Invalid address')
      if (!acceptDeliverySlot) return fail('DELIVERY_SLOT_NOT_ACCEPTED', 'Delivery slot not accepted')
      if (!String(sale.deliveryTimeSlotLabel || '').trim()) return fail('NOT_OPEN', 'Delivery slot not set')
    }

    const items = Array.isArray(event.items) ? event.items : []
    if (items.length === 0) return fail('BAD_REQUEST', 'Empty items')

    const orderId = buildOrderId(sale._id, openId)
    let existing = null
    try {
      const existingRes = await db.collection('orders').doc(orderId).get()
      existing = existingRes && existingRes.data
    } catch (err) {
      existing = null
    }
    if (existing && existing.status === 'CANCELLED') {
      if (String(existing.cancelledByOpenId || '') !== openId) {
        return fail('ORDER_CANCELLED', '订单已被店主取消，请联系店主')
      }
    }

    const incomingQtyById = new Map()
    for (const it of items) {
      const dishId = it && it.dishId
      const qty = Number(it && it.qty)
      if (!dishId || !Number.isFinite(qty) || qty <= 0) continue
      incomingQtyById.set(dishId, (incomingQtyById.get(dishId) || 0) + Math.floor(qty))
    }
    if (incomingQtyById.size === 0) return fail('BAD_REQUEST', 'Empty items')

    const allowed = new Set((sale.dishIds || []).filter(Boolean))
    for (const dishId of incomingQtyById.keys()) {
      if (!allowed.has(dishId)) return fail('ITEM_NOT_ALLOWED', 'Item not allowed')
    }

    const mergedQtyById = new Map()
    const existingItemById = new Map()
    if (existing && existing.status === 'ACTIVE' && Array.isArray(existing.items)) {
      for (const oldItem of existing.items) {
        const dishId = oldItem && oldItem.dishId
        const qty = Number(oldItem && oldItem.qty)
        if (!dishId || !Number.isFinite(qty) || qty <= 0) continue
        mergedQtyById.set(dishId, (mergedQtyById.get(dishId) || 0) + Math.floor(qty))
        existingItemById.set(dishId, oldItem)
      }
    }
    for (const [dishId, qty] of incomingQtyById.entries()) {
      mergedQtyById.set(dishId, (mergedQtyById.get(dishId) || 0) + qty)
    }
    if (mergedQtyById.size === 0) return fail('BAD_REQUEST', 'Empty items')

    const mergedDishIds = Array.from(mergedQtyById.keys())
    const dishList = await getDishesByIds(mergedDishIds)
    const dishMap = new Map(dishList.map((d) => [d._id, d]))
    for (const dishId of incomingQtyById.keys()) {
      if (!dishMap.has(dishId)) return fail('ITEM_NOT_ALLOWED', 'Item not allowed')
    }

    const orderItems = []
    let totalQty = 0
    let totalAmountCents = 0
    for (const dishId of mergedDishIds) {
      const qty = mergedQtyById.get(dishId) || 0
      if (qty <= 0) continue
      const d = dishMap.get(dishId)
      const oldItem = existingItemById.get(dishId) || null
      const unitPriceCents = d ? Number(d.priceCents || 0) : Number(oldItem && oldItem.unitPriceCents)
      const dishName = d ? d.name : String((oldItem && oldItem.dishName) || '')
      if (!Number.isFinite(unitPriceCents) || unitPriceCents < 0 || !dishName) return fail('ITEM_NOT_ALLOWED', 'Item not allowed')
      const lineTotalCents = unitPriceCents * qty
      totalQty += qty
      totalAmountCents += lineTotalCents
      orderItems.push({
        dishId,
        dishName,
        unitPriceCents,
        qty,
        lineTotalCents,
      })
    }

    const payment = event.payment || {}
    const paymentMethod = String(payment.method || 'cash')
    const paidStatus = String((existing && existing.payment && existing.payment.paidStatus) || 'UNPAID')

    const now = db.serverDate()
    const doc = {
      saleId: sale._id,
      customerOpenId: openId,
      status: 'ACTIVE',
      fulfillmentType,
      deliveryTimeSlotLabelSnapshot: fulfillmentType === 'delivery' ? String(sale.deliveryTimeSlotLabel || '').trim() : null,
      acceptDeliverySlot: fulfillmentType === 'delivery' ? true : false,
      contact: { phone },
      address:
        fulfillmentType === 'delivery'
          ? {
              line1: String(address.line1 || '').trim(),
              line2: String(address.line2 || '').trim(),
              postalCode: String(address.postalCode || '').trim(),
              city: String(address.city || '').trim(),
              country: 'FR',
            }
          : null,
      payment: { method: paymentMethod, paidStatus },
      remark: String(event.remark || '').trim(),
      items: orderItems,
      totals: { qty: totalQty, amountCents: totalAmountCents },
      updatedAt: now,
    }
    let auditAction = 'CREATE'
    if (existing) {
      await db.collection('orders').doc(orderId).update({
        data: {
          ...doc,
          cancelledAt: _.remove,
          cancelledByOpenId: _.remove,
          // Keep original creation time when customer modifies order.
          createdAt: existing && existing.createdAt ? existing.createdAt : now,
        },
      })
      auditAction = 'UPDATE'
    } else {
      await db.collection('orders').doc(orderId).set({
        data: {
          ...doc,
          createdAt: now,
        },
      })
    }
    await db.collection('orderAuditLogs').add({
      data: {
        orderId,
        action: auditAction,
        byOpenId: openId,
        at: now,
      },
    })
    return ok({ orderId, mode: auditAction })
  }

  return fail('UNKNOWN_ACTION', `Unknown action: ${action || ''}`)
}

