  }
}

function buildSlotLabel(slotDate, slotStart, slotEnd) {
  const d = String(slotDate || '').trim()
  const s = String(slotStart || '').trim()
  const e = String(slotEnd || '').trim()
  if (!d || !s || !e) return ''
  return `${d} ${s}-${e}`
}

function normalizePhone(phone) {
