  const addresses = normalizeStoredAddresses(doc && doc.addresses)
  let defaultAddressId = String((doc && doc.defaultAddressId) || '').trim()
  if (!addresses.some((a) => a.id === defaultAddressId)) {
    defaultAddressId = addresses[0] ? addresses[0].id : ''
  }
  return {
