const HOME_SNAPSHOT_KEY = 'home_bootstrap_cache_v5'

function normalizeSale(raw) {
  if (!raw || typeof raw !== 'object') return null
  return {
    isOpen: !!raw.isOpen,
    saleId: String(raw.saleId || raw._id || '').trim(),
    deliveryTimeSlotLabel: String(raw.deliveryTimeSlotLabel || '').trim(),
    _id: String(raw._id || raw.saleId || '').trim() || undefined,
  }
}

function normalizeSnapshot(raw) {
  if (!raw || typeof raw !== 'object') return null
  const sale = normalizeSale(raw.sale)
  const dishes = Array.isArray(raw.dishes) ? raw.dishes : []
  const profile = raw.profile && typeof raw.profile === 'object' ? raw.profile : null
  if (!sale) return null
  return {
    sale,
    dishes,
    profile,
    updatedAt: Number(raw.updatedAt || 0) || 0,
  }
}

function getHomeSnapshot() {
  const raw = wx.getStorageSync(HOME_SNAPSHOT_KEY)
  return normalizeSnapshot(raw)
}

function saveHomeSnapshot(input) {
  const normalized = normalizeSnapshot({
    sale: input && input.sale,
    dishes: input && input.dishes,
    profile: input && input.profile,
    updatedAt: Date.now(),
  })
  if (!normalized) return
  wx.setStorageSync(HOME_SNAPSHOT_KEY, normalized)
}

function clearHomeSnapshot() {
  wx.removeStorageSync(HOME_SNAPSHOT_KEY)
}

module.exports = {
  HOME_SNAPSHOT_KEY,
  getHomeSnapshot,
  saveHomeSnapshot,
  clearHomeSnapshot,
}

