  return (n / 100).toFixed(2)
}

function euroToCent(str) {
  const s = String(str || '').trim().replace(',', '.')
  if (!s) return 0
  const n = Number(s)
  if (Number.isNaN(n)) return 0
  return Math.round(n * 100)
}

