        activeSale: (dashRes.data && dashRes.data.activeSale) || null,
        stats: (dashRes.data && dashRes.data.stats) || { orderCount: 0 },
      }
    }
  }

  return setSnapshot({
    sale: homeRes.data.sale,
    dishes: homeRes.data.dishes,
    profile: homeRes.data.profile,
    admin,
  })
}

module.exports = {
  getSnapshot,
