  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, text, url) => `${text} (${url})`)
  // Remove code fences and inline code markers.
  s = s.replace(/```[\s\S]*?```/g, (m) => m.replace(/```/g, ''))
  s = s.replace(/`([^`]+)`/g, '$1')
