function pad2(n) {
  return n < 10 ? `0${n}` : `${n}`
}

function formatTime(ts) {
  if (!ts) return ''
  const d = typeof ts === 'number' ? new Date(ts) : new Date(String(ts))
  if (Number.isNaN(d.getTime())) return ''
  const Y = d.getFullYear()
  const M = pad2(d.getMonth() + 1)
