+      dishNameSnapshot: String((it && it.dishNameSnapshot) || '').trim(),
+      needQty: Math.max(0, toSafeInt(it && it.needQty, 0)),
+      preparedQty: Math.max(0, toSafeInt(it && it.preparedQty, 0)),
+    }))
