+async function getSaleProductionProgress(saleId) {
+  const id = String(saleId || '').trim()
+  if (!id) return null
+  try {
+    const r = await db.collection('saleProductionProgress').doc(id).get()
+    const data = r && r.data ? r.data : null
+    if (!data) return null
+    return {
