            return status === SALE_STATUS.OPEN || status === SALE_STATUS.CLOSED || status === SALE_STATUS.FULFILLING
          })
          activeSaleId = String((fallbackSale && fallbackSale._id) || '').trim()
        } catch (err) {
          activeSaleId = ''
        }
