          const runtimeRef = runtimeCtx.ref
          const runtime = runtimeCtx.data || { currentSaleId: null }
          const currentSaleId = String((runtime && runtime.currentSaleId) || '').trim()
          if (!currentSaleId || currentSaleId !== saleId) {
